/* Normally generated by configure from path.h.in, which the Debian repack ships without a
   generated copy. None of these locations exist on a calculator: the Nspire build compiles its
   help and locale data in, so these only have to satisfy the includes. */
#define giac_html_location "/usr/share/giac/doc/"
#define giac_aide_location "/usr/share/giac/aide_cas"
#define giac_locale_location "/usr/share/locale/"
#define giac_gnuplot_location ""
